"Abstand Anfang / Ende":"Distancia inicio / fin",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"A distancia ao inicio / ao fin converte a aba nunha aba parcial. Os demais perfís pechados do esbozo convértense en recortes na placa. Buratos e fiestras nunha aba: centro ao longo da aresta (nunha aresta curva, ao longo do arco), centro desde o fin da dobra, tamaño – tamén aparecen no desenvolvemento. Se unha aresta curva pasa sen quebra á súa aresta veciña e ambas teñen unha aba co mesmo ángulo de dobra, as abas continúan unha na outra sen recorte de alivio. «Contorno de esbozo» corta da aba os perfís pechados dun esbozo: o seu X vai ao longo da aresta, o seu Y cara ao interior da aba, o punto cero está no inicio da aresta, no fin da dobra (desprazable).",
