"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Selecciona todas as caras que deben desaparecer (nunha cavidade as paredes e o fondo, nun burato a parede, nun empalme a cara redondeada). As caras veciñas prolónganse sobre o oco. O paso recalcúlase ao cambiar o corpo; a primeira vez cárgase para isto o núcleo xeométrico completo (uns segundos).",
