"Darstellungsqualität":"Calidade de visualización",
"Das Bild konnte nicht gelesen werden.":"Non se puido ler a imaxe.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"A imaxe está sobre o plano como modelo. Despois axusta tamaño, posición, xiro e opacidade no panel de propiedades (p. ex. o largo segundo unha medida coñecida).",
"Das Ergebnis des Geometriekerns ist unlesbar":"O resultado do núcleo xeométrico é ilexible",
"Das Ergebnis konnte nicht geschrieben werden":"Non se puido escribir o resultado",
"Das Maß muss größer als 0 sein.":"A cota debe ser maior que 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"A malla permanece como malla de triángulos (non B-Rep). Edítase en MALLA: Reparar, Reducir, Suavizar, Corte por plano … As estratexias de fresado 3D en Fabricación poden mecanizala directamente.",
"Das Netz hat {0} Dreiecke. Jedes wird eine Fläche des Körpers – das dauert lange und macht den Körper träge. Vorher „Reduzieren“ ist meist besser.\n\nTrotzdem umwandeln?":"A malla ten {0} triángulos. Cada un converterase nunha cara do corpo – isto leva moito tempo e fai o corpo lento. Normalmente é mellor «Reducir» antes.\n\nConverter igualmente?",
"Das Netz ist nicht geschlossen. Zuerst „Reparieren“ ausführen – ein Körper braucht eine geschlossene Hülle.":"A malla non está pechada. Executa primeiro «Reparar» – un corpo precisa unha envoltura pechada.",
"Das Netz reicht in Z von {0} bis {1} mm, in X von {2} bis {3} mm, in Y von {4} bis {5} mm. Punkte, die weniger als die Toleranz von einer Geraden abweichen, entfallen.":"A malla esténdese en Z de {0} a {1} mm, en X de {2} a {3} mm, en Y de {4} a {5} mm. Os puntos que se desvían dunha recta menos que a tolerancia elimínanse.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"O perfil non debe cruzar o eixe. Unha liña aberta no esbozo pode servir de eixe.",
"Das Profil mit den jetzigen Werten überschreiben":"Sobrescribir o perfil cos valores actuais",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"O perfil guíase ao longo dunha liña/polilíña. O mellor é debuxar o perfil perpendicular ao inicio da traxectoria (p. ex. perfil en XZ, traxectoria en XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"O perfil estampase en relevo ou rehundido a partir do plano do esbozo.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"A peza en bruto é o paralelepípedo arredor do corpo seleccionado (máis o desfase).",
"Das Setup hat keine Operationen.":"O setup non ten operacións.",
"Das Teil ist für die Senkung zu dünn (Senktiefe {0} mm, Dicke {1} mm).":"A peza é demasiado fina para o abuxardado (profundidade {0} mm, espesor {1} mm).",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"A ferramenta fresa en círculos cuxo centro se despraza ao longo do canal. Nunca está engranada en todo o seu ancho; isto permite grandes profundidades de corte e coida a fresa e o fuso. A fresa debería ter ao redor do 60 % da largura do canal.",
"Das Werkzeug schneidet die Fläche nicht":"A ferramenta non corta a superficie",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"A ferramenta corta cara ás caras seleccionadas ata acadar os sobremetais indicados.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"A ferramenta mergúllase en vertical coma unha broca, fileira por fileira, ata o modelo máis o sobremetal. A forza de corte actúa ao longo do fuso: axeitado para ferramentas longas, cavidades profundas e máquinas pouco ríxidas. A ferramenta debe cortar polo centro.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"A ferramenta evita estas caras respectando as distancias de seguridade indicadas (grapas, torno).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"A ferramenta evita estas caras mentres mecaniza caras próximas e respecta as distancias de seguridade.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"O primeiro Esc só cancela a ferramenta ou a selección: un Esc de máis non pecha o esbozo",
"Das ist eine runde Fläche – bitte eine ebene Fläche anklicken.":"Esta é unha cara redonda – prema nunha cara plana.",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Isto non é un burato (empalme ou espiga) – fai clic na parede interior dun burato.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Isto non é un burato (cara cilíndrica) – fai clic na parede do burato.",
"Das ist keine WerkFab-Design-Datei.":"Este non é un ficheiro de deseño de WerkFab.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"Esta non é unha aresta oblicua: preme nos dous extremos da aresta do chafrán.",
"Datei":"Ficheiro",
"Datei ist keine WerkFab-Einstellungsdatei.":"O ficheiro non é un ficheiro de preferencias de WerkFab.",
"Datei konnte nicht geöffnet werden:":"Non se puido abrir o ficheiro:",
