"Dieser Browser unterstützt keine SpaceMouse (WebHID). Bitte Chrome, Edge oder die Desktop-App verwenden.":"Este navegador non admite SpaceMouse (WebHID). Usa Chrome, Edge ou a aplicación de escritorio.",
