"Dieses Gelenk bewegt sich mit dem gewählten (z. B. Zahnräder: Übersetzung = −Zähne₁/Zähne₂). Negative Werte drehen gegenläufig.":"Esta articulación móvese coa escollida (p. ex. engrenaxes: relación = −dentes₁/dentes₂). Os valores negativos xiran en sentido contrario.",
