"Drehen: C-Achse und angetriebenes Werkzeug ein":"Torneado: eixe C e ferramenta motorizada activados",
"Drehen: Das Teil muss rotationssymmetrisch um die Z-Achse liegen. Z0 = Planfläche oben, X = Durchmesser.":"Torneado: a peza ten que ser simétrica de revolución arredor do eixe Z. Z0 = cara frontal arriba, X = diámetro.",
"Drehen: Drehpunkt anklicken, dann den Winkel mit der Maus zeigen (Vorschau). Esc beendet.":"Xirar: fai clic no punto de xiro e despois indica o ángulo co rato (vista previa). Esc remata.",
"Drehen: Durchmesser, auf dem der Revolver schaltet (Okuma, LinuxCNC). 0 = Rohteil-Ø + 200 mm":"Torneado: diámetro no que indexa a torreta (Okuma, LinuxCNC). 0 = Ø da peza en bruto + 200 mm",
"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"Xirar: seleccione elementos, faga clic no punto de xiro e indique o ángulo co rato (vista previa); tamén como copia",
"Drehen: Gewindeschnitt":"Torneado: pasada de rosca",
"Drehen: Gewindezyklus":"Torneado: ciclo de rosca",
"Drehen: Polar-Interpolation aus":"Torneado: interpolación polar desactivada",
"Drehen: Polar-Interpolation ein (X Durchmesser, C in mm; leer = X/C in Grad)":"Torneado: interpolación polar activada (X diámetro, C en mm; baleiro = X/C en graos)",
"Drehen: Schlichtzyklus (Kontur des Schruppzyklus)":"Torneado: ciclo de acabado (contorno do ciclo de desbaste)",
"Drehen: Schruppzyklus ({contour} = Konturzeilen)":"Torneado: ciclo de desbaste ({contour} = liñas de contorno)",
"Drehen: Vorsatz erste Konturzeile":"Torneado: prefixo da primeira liña de contorno",
"Drehen: Vorsatz letzte Konturzeile":"Torneado: prefixo da última liña de contorno",
"Drehen: Winkel (°, gegen den Uhrzeigersinn); Drehpunkt X; Drehpunkt Y; Kopien (0 = drehen)":"Xirar: ángulo (°, en sentido antihorario); punto de xiro X; punto de xiro Y; copias (0 = xirar)",
"Drehen: Y-Achse aus":"Torneado: eixe Y desactivado",
"Drehen: Y-Achse ein (Ebene X/Y; hier auch die C-Klemmung der Maschine eintragen)":"Torneado: eixe Y activado (plano X/Y; introduza aquí tamén a suxeición C da máquina)",
"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"Torneado: Z diante da cara plana no que indexa a torreta. 0 = distancia de seguridade + 100 mm",
"Drehen: Zylinder-Interpolation aus":"Torneado: interpolación cilíndrica desactivada",
"Drehen: Zylinder-Interpolation ein ({cylr} = Radius; leer = Z/C ohne)":"Torneado: interpolación cilíndrica activada ({cylr} = raio; baleiro = Z/C sen)",
"Drehen: angetriebenes Werkzeug und C-Achse aus":"Torneado: ferramenta motorizada e eixe C desactivados",
"Drehen: einen Winkel angeben.":"Xirar: indica un ángulo.",
"Drehgelenk":"Xunta de revolución",
"Drehgelenk angelegt – mit dem Regler bewegen.":"Articulación de xiro creada: móvea co control deslizante.",
"Drehgeschwindigkeit":"Velocidade de xiro",
"Drehmaschine mit Y-Achse: Schlüsselflächen, Konturen und Taschen auf der Planfläche fahren mit feststehendem Teil (C fest) in X und Y – genauer als die Polar-Interpolation. Was über den Y-Weg hinausgeht, bleibt bei der Polar-Interpolation.":"Torno con eixe Y: as caras de chave, os contornos e as cavidades na cara frontal execútanse coa peza parada (C fixo) en X e Y, con maior precisión que a interpolación polar. O que exceda o percorrido de Y mantense coa interpolación polar.",
