"Durchzug":"Collarín",
"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}) – der Rand reißt dabei meist ein.":"Collarín {0}: o furado previo de Ø {1} mm ábrese ata Ø {2} mm (factor {3}) – o bordo adoita rachar ao facelo.",
"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}).":"Collarín {0}: o furado previo de Ø {1} mm ábrese ata Ø {2} mm (factor {3}).",
"Durchzug {0}: liegt {1} mm neben dem Rand (weniger als 2 × Blechdicke) – der Rand beult aus.":"Collarín {0}: está a {1} mm do bordo (menos de 2 × grosor da chapa) – o bordo abomba.",
"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"Collarín {0}: demasiado alto para este burato (o furado previo quedaría sen diámetro)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Collarín: o bordo dun burato redondo estírase cara arriba ata formar un collarín, por exemplo como collarín para rosca. O diámetro do burato do esbozo é o diámetro interior acabado; no patrón de corte córtase o furado previo, máis pequeno.",
