"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"Atallos personalizados: abre o menú do grupo (▾) na barra de ferramentas, fai clic en ⋮ xunto ao comando → “Cambiar o atallo de teclado …”.",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"As cotas e notas propias pódense arrastrar na folla co rato (distancia da liña de cota, ángulo da liña de chamada, raio do arco de ángulo). Dous clics en recantos = cota de lonxitude. Un clic no bordo dun círculo na vista superior = diámetro (ou raio). Ángulo: primeiro o vértice e despois un punto en cada lado. Chafrán: os dous extremos da aresta oblicua; dá p. ex. 2×45°. No campo de texto despois de cada cota hai un complemento como ±0,1, H7 ou 4×.",
