"Erhebung braucht zwei Skizzen mit geschlossenen Profilen auf verschiedenen Ebenen.":"Loft necesita dous esbozos con perfís pechados en planos diferentes.",
"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"Loft necesita dous esbozos cunha curva cada un (en planos diferentes).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"Loft non posible – revise as seccións transversais (un perfil pechado cada unha, sen torcer)",
"Erhebung nicht möglich – je Skizze eine Kurve, gleiche Richtung, nicht verdreht":"Loft non posible – unha curva por esbozo, mesma dirección, sen torcer",
"Ersetzt den Standard-Kurzbefehl „{0}“.":"Substitúe o atallo predeterminado «{0}».",
"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Primeiro fai clic na cara do corpo que se move, despois na cara de destino do outro corpo. O corpo xírase e desprázase ata que o primeiro punto de clic está sobre o segundo e as caras quedan unha sobre outra.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Primeiro fai clic na aresta do corpo que se move, despois na aresta de destino do outro corpo. As arestas rectas fanse coincidentes (centro con centro); nas arestas circulares – burato e espiga – os eixes oriéntanse igual e os centros únense.",
"Erst ein Setup anlegen.":"Primeiro cree un setup.",
"Erst ein Setup mit Operationen anlegen.":"Primeiro cree un setup con operacións.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Selecciona primeiro un esbozo ou un plano de construción: despois Ctrl+8 mira perpendicularmente a el.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Primeiro crea un corpo en DESEÑO ou insire unha malla (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"Primeiro cree un corpo en DESEÑO.",
