"Fläche":"Cara",
"Fläche am bewegten Körper gewählt":"Cara do corpo que se move seleccionada",
"Fläche anklicken – die Bohrung entsteht mit":"Prema nunha cara – o burato créase á vez",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"Prema nunha cara: en cada punto premido créase o burato pasante para o parafuso (ISO 273, serie media) a través de todas as pezas que están alí unhas sobre outras – para parafusos avellanados con avellanado de 90°, para parafusos de cabeza cilíndrica, se se desexa, con abuxardado cilíndrico (DIN 974-1, serie 1) tan profundo como a cabeza. O parafuso queda aloxado de seguido no burato. O burato e o parafuso pódense cambiar despois na liña do tempo.",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Faga clic nunha cara dun corpo: o seu bordo engádese ao esbozo como contorno. Facer clic nunha aresta proxecta só esa aresta (os círculos seguen sendo círculos). A xeometría proxectada é violeta.",
"Fläche ersetzen":"Substituír cara",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"Substituír cara: levar unha cara plana a outro plano – o corpo crece ou acórtase",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"Área detrás das fiestras – aplícase se arriba se escolle o deseño «Propio»",
"Fläche löschen":"Eliminar cara",
"Fläche löschen: Bohrungen, Taschen, Verrundungen oder Fasen entfernen – die Nachbarflächen schließen die Lücke":"Eliminar cara: quitar buratos, cavidades, empalmes ou chafráns – as caras veciñas pechan o oco",
"Fläche oder Kante unter dem Mauszeiger farbig anzeigen":"Mostrar en cor a cara ou aresta baixo o punteiro do rato",
"Fläche versetzen":"Desprazar cara",
"Fläche versetzen: ebene Flächen verschieben, Bohrungen und Zapfen im Durchmesser ändern":"Desprazar cara: mover caras planas, cambiar o diámetro de buratos e pivotes",
"Fläche wählen":"Seleccione a cara",
"Fläche wählen, die getrimmt wird":"Seleccione a superficie que se vai recortar",
"Fläche zum Antasten in Z":"Cara para palpar en Z",
"Fläche {0}":"Cara {0}",
"Flächen":"Caras",
"Flächen (alle Kanten ringsum)":"Caras (todas as arestas arredor)",
"Flächen (aufeinander legen)":"Caras (poñer unha sobre outra)",
"Flächen am Körper":"Caras do corpo",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Planos no extremo da peza (dous planos, cadrado, hexágono) cunha fresa de vástago motorizada ao longo de Z. Anchura entre planos = dobre da distancia do plano ao eixe de rotación. X e C móvense xuntos (interpolación polar, Fanuc G12.1); sen este modelo no posprocesador sácanse pasos curtos de X/C.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Prema nas caras que se engrosarán (premer de novo quita).",
"Flächen anklicken, die geneigt werden (erneut klicken entfernt).":"Preme nas caras que se queren inclinar (outro clic quita a selección).",
"Flächen anklicken, die offen sein sollen.":"Preme nas caras que deben quedar abertas.",
