"Fusion-360-Dateien (.f3d) sind ein geschlossenes Autodesk-Format und können nicht gelesen werden.\n\nIn Fusion 360: Datei → Exportieren → STEP (.stp) wählen und diese Datei hier importieren.":"Os ficheiros de Fusion 360 (.f3d) son un formato pechado de Autodesk e non se poden ler.\n\nEn Fusion 360: escolle Ficheiro → Exportar → STEP (.stp) e importa aquí ese ficheiro.",
