"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"Percorre todas as arestas exteriores vivas accesibles desde arriba e rómpeas a profundidade de rebarbado: coa fresa de chafrán como chafrán (eixe da ferramenta vertical, punta fóra da aresta), coa fresa esférica/lollipop arredondadas.",
