"Gemeinsame Schnittkanten nur einmal schneiden":"Cortar as arestas de corte comúns só unha vez",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"Arestas de corte comúns: se dúas pezas recortadas están separadas exactamente unha largura de corte (ao aniñar, introduza a largura de corte como distancia), as súas traxectorias coinciden na aresta común e córtanse só unha vez. A entrada de corte nunca está nunha peza veciña: se xunto a un contorno non hai refugallo libre, o puncionado faise sobre o contorno. Despois de «Vista previa», unha imaxe por folla mostra a traxectoria antes de gardar os ficheiros.",
