"Gerade (radial)":"Recta (radial)",
"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Liñas rectas do esbozo que non pertencen a ningún perfil (tamén liñas auxiliares). Dobra: a liña é o centro da zona de dobra e o esbozo é alí o patrón de corte – a peza máis grande da placa queda onde está, todo o que está máis alá da liña xira coas súas abas. A liña vale para toda a placa. Nervadura: un nervio ao longo da liña, redondo na sección e nos extremos; a chapa mantén o seu grosor.",
