"Geschlossen":"Pechado",
"Geschlossen (Gehrung)":"Pechado (inglete)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Pechado: as abas de dous bordos veciños chegan ata a bisectriz do canto e deixan aí a fenda. O alivio de canto está onde se cruzan as zonas de dobrado – no desenvolvemento e na peza dobrada. Tamén unha aba nun bordo curvo córtase a inglete nun canto real (alí sen alivio de canto).",
"Geschlossene Kette {0}":"Cadea pechada {0}",
"Geschlossene Profile begrenzen den Bereich.":"Os perfís pechados limitan a área.",
"Geschlossene Profile der aktiven Skizze farbig füllen":"Encher en cor os perfís pechados do esbozo activo",
"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Os perfís pechados convértense en superficies planas – p. ex. tapa e fondo, para despois coser as superficies nun corpo.",
