"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an.":"Burato roscado na peza inferior: o burato pasante remata onde comeza a peza inferior; alí créase o burato previo da rosca coa rosca – tres filetes máis fondo do que chega o parafuso, ou por toda a peza. Se só hai unha peza baixo o punto, esta recibe a rosca desde a cara.",
