"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"Os corpos importados non teñen historial de deseño, pero poden seguir editándose (empalme, chafrán, corte …) e usarse para CAM. Con „Eixe Y cara arriba“ os modelos de programas con Y cara arriba colócanse correctamente.",
