"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"A primeira curva de cada esbozo – aberta ou pechada. As curvas únense cunha pel (superficie sen grosor).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Un ficheiro por folla. A traxectoria discorre xunto ao contorno, no refugallo, a media largura de corte (ao fresar, media fresa); os recortes van antes do contorno da súa peza e cada contorno comeza cunha entrada de corte desde o refugallo. As persianas córtanse sobre a súa liña. Pontes de suxeición: tantos puntos por contorno quedan sen cortar (láser, plasma, auga a presión: o feixe interrómpese aí; fresado: a fresa levántase ata a metade do grosor da chapa); os contornos de menos de 40 mm non as levan. «Control» determina como se acende e se apaga o feixe; o tempo de perforación escríbese como G4 no programa, salvo que o control perfore por si mesmo. O punto cero é o recanto inferior esquerdo da folla; ao fresar, Z0 é a cara superior da chapa. Comprobe o programa na máquina ou nun simulador NC antes de usalo.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Cada eixe por separado: faga clic nunha aresta, vértice, cara ou burato. Os eixes sen definir tómanse do punto da peza en bruto.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Cada operación como subprograma (LBL) ao final do programa, chamada con CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Cada círculo do esbozo é un centro de burato. Furase en sentido contrario á normal do esbozo (cara ao material).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Cada círculo do esbozo repítese xirado arredor do centro (en coordenadas do esbozo) – un círculo á distancia do radio do círculo primitivo dá un círculo de buratos.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Cada círculo do esbozo convértese nunha retícula: separacións en X e Y do esbozo (tamén negativas).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Agora un punto no segundo lado.",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Agora move cada dirección unha vez ata o tope: deslizar, tirar, empurrar, inclinar, xirar (10 s) …",
