"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"Aresta {0}: non se pode fabricar un ángulo de dobra superior a 180°.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Aresta {0}: aba nunha aresta curva – o seu bordo comprímese un {1} % durante a conformación (risco de engurras); o desenvolvemento é aí unha aproximación.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Aresta {0}: aba nunha aresta curva – o seu bordo estírase un {1} % durante a conformación (risco de fisuras); o desenvolvemento é aí unha aproximación.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Aresta {0}: a medida da aba de {1} mm é menor ca a dobra ({2} mm)",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"Aresta {0}: o arco é demasiado pechado para esta aba",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"Aresta {0}: as distancias non deixan ningunha aba.",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Aresta {0}: a aba cruza unha liña de dobra – fai que remate antes da dobra con «Distancia inicio / fin»",
"Kante {0}: die Lasche liegt in einer Biegezone":"Aresta {0}: a aba está nunha zona de dobra",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"Aresta {0}: un recorte pertence a unha aba que non existe.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Aresta {0}: un recorte na aba está a {1} mm da dobra (menos de 2 × grosor da chapa) – deformarase ao dobrar.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Aresta {0}: un recorte está a {1} mm da dobra (menos de 2 × o grosor da chapa) – deformarase ao dobrar.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"Aresta {0}: un recorte sobresae da aba.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Aresta {0}{1}: a aba de {2} mm é máis curta ca 2 × o grosor da chapa – case non se pode dobrar na prensa dobradora.",
