"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"Solta a tapa e escolle “Calibrar o punto cero”. Despois proba cada dirección: a barra debe moverse e, en repouso, quedar na zona morta gris.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Deslizar a tapa = desprazar, empurrar/tirar = zoom, inclinar e xirar = xirar o modelo. Nos esbozos só desprazamento e zoom. SpaceMouse Pro/Enterprise: T, F, R = vista superior, fronte, dereita. Se non pasa nada: pecha un momento o controlador de 3Dconnexion e volve conectar.",
