"Kieme: die Linie ist ein Schlitz, das Blech daneben wird zu einer Haube aufgestellt, die an beiden Enden des Schlitzes in die Platte ausläuft (Lüftungsschlitz). Im Zuschnitt ist der Schlitz ein Schnitt.":"Persiana: a liña é unha ranura, a chapa xunto a ela érguese formando unha cuberta que remata na placa nos dous extremos da ranura (ranura de ventilación). No patrón de corte a ranura é un corte.",
