"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"Contorno con {0} puntos – Okuma: G85 (LAP) con contorno G81…G80, Fanuc: G71 P…Q…. O control desbasta coa súa propia distribución; a simulación aquí é a traxectoria de WerkFab.",
