"Konturauswahl":"Selección de contornos",
"Konturen außen und innen":"Contornos exteriores e interiores",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Os contornos seguen o bordo das áreas escuras. A liña central vai polo medio dos trazos – axeitada para gravados e debuxos de liñas. „Rectas, arcos e círculos“ detecta arestas rectas, esquinas vivas, curvas e círculos; „Polilíñas“ segue a imaxe punto a punto. Despois axusta a escala se é preciso con „Calibrar modelo“ ou „Escalar“.",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"Os contornos con compensación de raio no control (RL/RR) aproxímanse e abandónanse con APPR/DEP; o control calcula o punto auxiliar e a compensación por si mesmo",
