"Kurven":"Curvas",
"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Curvas dun esbozo na cara frontal (transversal ao eixe de rotación) cunha fresa motorizada ao longo de Z (X e C móvense xuntos; Fanuc: interpolación polar G12.1). As curvas abertas fresanse de ida e volta. Profundidade desde a cara frontal.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"As curvas dun esbozo situado ao longo do eixe de rotación envólvense na circunferencia e fresanse cunha fresa motorizada orientada ao eixe (Z e C móvense xuntos; Fanuc: interpolación cilíndrica G7.1). O plano do esbozo determina o ángulo no que se atopa o contorno; os tramos horizontais do esbozo convértense en arcos arredor da peza. Profundidade desde o diámetro exterior.",
"Kurzbefehl":"Atallo",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Os percorridos curtos (ata a distancia de mantemento) fanse abaixo co avance de transición en vez de pola altura de retirada; sen comprobación de colisións, así que convén mantelo pequeno.",
