"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Varias arestas conectadas contan como un só tramo: o radio vai desde o inicio da cadea ata o seu fin, e os puntos de control danse en % da lonxitude total da cadea. Isto calcúlao o núcleo xeométrico completo.",
