"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"Con puntos de control o radio pasa polos valores indicados (posición en % da lonxitude da aresta). Isto calcúlao o núcleo xeométrico completo; a primeira vez tarda uns segundos en cargar.",
"Mit dem 3D-Taster kann nicht zerspant werden":"Co apalpador 3D non se pode mecanizar",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Comparar coa peza acabada: verde = en medida, azul = material restante, vermello = demasiado profundo",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Move o rato xunto a un contorno (o lado determina a dirección) · Esc remata",
"Mit diesem Werkzeug kann nicht gefräst werden":"Con esta ferramenta non se pode fresar",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"Cun macho de roscar use só o ciclo “Roscado con macho” – un ciclo de furado rompería o macho",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Con varias pasadas, a profundidade da rosca fresase por etapas que retiran aproximadamente a mesma cantidade cada unha; coida as fresas de rosca pequenas e os materiais duros. A pasada en baleiro repite a última traxectoria sen avance en profundidade.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"Con «Ciclos de furado» no programa NC sácanse ciclos do control (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85); se non, movementos desenvolvidos.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"Con «Manter o orixinal» o orixinal e a imaxe espello pasan a ser unha malla; os puntos do plano de simetría únense – dunha metade aberta resulta así unha peza pechada.",
