"Noch keine Vorlagen. Eine Vorlage speichert Strategien mit allen Einstellungen (Werkzeug, Schnittdaten, Höhen, Durchgänge, Verknüpfung) zum Wiederverwenden in anderen Setups und Designs.":"Aínda non hai modelos. Un modelo garda estratexias con todos os axustes (ferramenta, datos de corte, alturas, pasadas, vinculación) para reutilizalos noutros setups e deseños.",
