"Nur Außenkonturen (Zapfen) gehen als Steuerungszyklus":"Só os contornos exteriores (espigas) valen como ciclo do control",
"Nur Durchmesser (Form wie dieses Werkzeug)":"Só diámetro (forma coma esta ferramenta)",
"Nur Innenkonturen (Öffnungen)":"Só contornos interiores (aberturas)",
"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"Só as cavidades rectangulares e circulares valen como ciclo do control",
"Nur Skizze":"Só esbozo",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Mecanizar só o que unha fresa maior deixou nos currunchos.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Seguir só os tramos do contorno que unha fresa maior non alcanzou (cantos interiores, zonas estreitas). Sen arcos de entrada/saída, pestanas de suxeición nin pasadas de acabado; compensación no ordenador.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Só onde non chegou a ferramenta de referencia: zonas planas en paralelo, zonas empinadas como liña de auga. Cunha ferramenta da lista tamén se ten en conta a súa forma; por exemplo, o que unha fresa tórica deixa nos acordes.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Só as caras planas poden servir como plano de esbozo.",
"Nur ebene Flächen können extrudiert werden":"Só se poden extrudir caras planas",
"Nur ebene Flächen lassen sich ersetzen":"Só se poden substituír caras planas",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Só se poden desprazar caras planas e cilíndricas (buratos, espigas)",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Só caras planas que miran cara arriba, cara á ferramenta (horizontais neste setup).",
"Nur für Außen-Drehmeißel":"Só para ferramentas de torneado exterior",
"Nur in Operationen verwendete":"Só as usadas en operacións",
