"Nut angetrieben":"Ranura con ferramenta motorizada",
"Nut angetrieben (C-Achse)":"Rañura con ferramenta motorizada (eixe C)",
"Nut liegt nicht am Teil":"A rañura non está na peza",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Canal ao longo do eixe de rotación (p. ex. rañura de chaveta) cunha fresa motorizada orientada ao eixe; o fuso principal sostén a peza como eixe C. Largura do canal = Ø da fresa. Z inicial/final en Z do modelo; se o canal chega á cara frontal, a fresa entra de fronte, se non mergúllase no inicio. Profundidade desde o diámetro exterior.",
"Nutbreite bei Linien":"Largura do canal en liñas",
