"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"As arestas abertas móstranse en vermello. “Reparar” pecha os buratos.",
"Offene Linie in einer Skizze wählen":"Seleccione unha liña aberta nun esbozo",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"As curvas abertas ou pechadas extrúdense perpendicularmente ao esbozo – o resultado é unha superficie (parede sen grosor). Con „Engrosar“ ou „Coser“ convértese nun volume.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"As curvas abertas ou pechadas xíranse arredor do eixe – o resultado é unha superficie, non un volume.",
"Ohne Mutter":"Sen porca",
"Ohne eigene Taste gilt der Standard „{0}“.":"Sen unha tecla propia, aplícase a predeterminada «{0}».",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Sen „Modelada“ a rosca só se representa (rápido). Modelada, a forma da rosca córtase realmente, p. ex. para impresión 3D. Burato para M8 = Ø6,8.",
