"Okuma OSP-M Fräsen":"Okuma OSP-M fresado",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 non van ás coordenadas da máquina nese control (G53 anula a corrección de lonxitude da ferramenta) – retirada á altura de seguridade, non se emite ningún movemento de referencia XY",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: non se emite ningunha función de suavizado (G5.1 é de Fanuc) – axuste Hi-Cut/Super-NURBS na máquina",
