"Positiv = nach außen (mehr Material), negativ = nach innen. Ebene Flächen verschieben sich; bei einer Bohrung oder einem Zapfen ändert sich der Radius um den Abstand – eine Bohrung wird mit positivem Abstand enger.":"Positivo = cara fóra (máis material), negativo = cara dentro. As caras planas desprázanse; nun burato ou nunha espiga o radio cambia segundo a distancia – un burato estréitase cunha distancia positiva.",
"Positiver Abstand = in Richtung der Skizzennormalen. Taschen: Ausschneiden mit negativem Abstand.":"Distancia positiva = na dirección da normal do esbozo. Cavidades: cortar con distancia negativa.",
