"Prägung {0}: die Kontur ist schmaler als 2 × Blechdicke – es bleibt kein Hohlraum.":"Estampación {0}: o contorno é máis estreito que 2 × o grosor da chapa – non queda ningún oco.",
"Prägung {0}: lässt sich so nicht formen":"Estampación {0}: non se pode formar así",
"Prägung {0}: mit dieser Wandschräge lässt sie sich nicht formen":"Estampación {0}: non se pode formar con este ángulo da parede",
"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"Estampación {0}: {1} mm é máis alto que 3 × o grosor da chapa – cunha parede vertical a chapa rasga.",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt; das zweite Feld ist die Wandschräge (0° = senkrecht). Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"Estampación: o contorno non se corta, senón que se preme fóra da chapa na altura indicada; o segundo campo é o ángulo da parede (0° = vertical). Estampación avellanada: o bordo dun burato redondo prémese ata formar un cono de 90° – para parafusos de cabeza avellanada en chapa fina (− cara abaixo: parafuso desde arriba).",
