"Tasche":"Cavidade",
"Tasche Mantel":"Cavidade no perímetro",
"Tasche Mantelfläche (C-Achse)":"Cavidade no perímetro (eixe C)",
"Tasche Planfläche":"Cavidade na cara frontal",
"Tasche Planfläche (C-Achse)":"Cavidade na cara frontal (eixe C)",
"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Cavidade na circunferencia a partir dos contornos pechados dun esbozo que está ao longo do eixe de xiro (os contornos interiores quedan como illas). O esbozo enrólase sobre o diámetro; unha fresa de vástago accionada que apunta ao eixe baleira de dentro cara a fóra (Z e C móvense xuntos; Fanuc: interpolación cilíndrica G7.1). A fresa mergúllase nunha rampa ao longo do anel máis interior.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Cavidade na cara frontal a partir dos contornos pechados dun esbozo (os contornos interiores quedan como illas), cunha fresa de vástago motorizada ao longo de Z. O baleirado vai de dentro cara a fóra; a fresa mergullase en rampa ao longo da traxectoria máis interior e permanece abaixo dentro dun nivel. X e C móvense xuntos (Fanuc: interpolación polar G12.1). Profundidade desde a cara frontal.",
"Tasche mit Insel – der Steuerungszyklus kann keine Inseln":"Cavidade con illa – o ciclo do control non pode manexar illas",
"Tasche schmaler als das Werkzeug":"Cavidade máis estreita ca a ferramenta",
