"Verbindet die größten geschlossenen Profile der gewählten Skizzen (z. B. Rechteck unten, Kreis oben).":"Une os perfís pechados máis grandes dos esbozos seleccionados (p. ex. rectángulo abaixo, círculo arriba).",
