"Vermeiden":"Evitar",
"Vernetzung fehlgeschlagen:":"Fallou a mallado:",
"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Calcula de verdade dúas mallas pechadas entre si: as caras interiores desaparecen e as arestas de intersección volven mallarse. Só se calcula onde as dúas mallas poden atoparse – por iso unha malla grande cunha intervención pequena é rápida. Se dúas mallas grandes se solapan por completo, antes «Reducir».",
