"Verschleiß":"Desgaste",
"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"Unión parafusada: as arandelas e a porca colócanse xunto co parafuso dunha soa vez en cada burato seleccionado. O espesor de suxeición é a lonxitude do burato – a través de varias pezas se os seus buratos están aliñados e en contacto. Con porca proponse a lonxitude preferente máis curta coa que o parafuso sobresae dous filetes da porca.",
"Verschraubung: {0} – Klemmdicke {1} mm":"Unión parafusada: {0} – espesor de suxeición {1} mm",
"Verschraubung: {0} – die Schraube ist für die Klemmdicke {1} mm zu kurz (nötig: {2} mm)":"Unión parafusada: {0} – o parafuso é demasiado curto para o espesor de suxeición {1} mm (necesario: {2} mm)",
"Verschraubung: {0} – {1}; die Schraube ist für die Klemmdicke {2} mm zu kurz (nötig: {3} mm)":"Unión parafusada: {0} – {1}; o parafuso é demasiado curto para o espesor de suxeición {2} mm (necesario: {3} mm)",
