"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Envolve as curvas do esbozo no cilindro: X segue sendo X, a distancia transversal ao eixe convértese en arco sobre o Ø de desenvolvemento (rotación A). O esbozo debe ser paralelo ao eixe A, p. ex. nun plano tanxente. Fresase a profundidade fixa baixo a superficie da peza; para gravados, letras e canais arredor da peza.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Como o contorno 3D, pero a ferramenta baixa de forma continua sen chanzos; sen marcas de mergullo nas paredes empinadas.",
