"{0}: Die gewählte Maschine hat keine endlos drehende A-Achse":"{0}: a máquina escollida non ten un eixe A de rotación continua",
"{0}: Dieser Postprozessor hat keine Vorlage für die Verweilzeit – übersprungen":"{0}: Este posprocesador non ten modelo para o tempo de espera – omitido",
