"{0}: Drehzahl {1} > Maschinenmaximum {2} – begrenzt":"{0}: Velocidade do fuso {1} > máximo da máquina {2} – limitada",
"{0}: Ecke anklicken – Linienzug, Rechteck oder Treffpunkt zweier Linien. Das Werkzeug bleibt aktiv, Esc beendet.":"{0}: preme nun recanto: polilinea, rectángulo ou punto de encontro de dúas liñas. A ferramenta segue activa, Esc remata.",
"{0}: Fläche oder Kante im Modell anklicken.":"{0}: faga clic nunha cara ou aresta do modelo.",
"{0}: GRBL kennt keine Radiuskorrektur (G41/G42) – Bahn ohne Korrektur ausgegeben":"{0}: GRBL non ten compensación do raio da ferramenta (G41/G42) – traxectoria emitida sen compensación",
"{0}: Nullpunkt Y/Z liegt nicht auf der Drehachse A (Achse bei Y{1} Z{2}) – für 4-Achs-Simultan den Nullpunkt auf die Achse legen (Rohteil-Punkt Mitte Y/Z)":"{0}: o punto cero Y/Z non está no eixe de rotación A (eixe en Y{1} Z{2}) – para 4 eixes simultáneos, sitúa o punto cero no eixe (punto da peza en bruto centro Y/Z)",
"{0}: Postprozessor ohne Drehzyklus – als Bahn ausgegeben":"{0}: Posprocesador sen ciclo de torneado – emitido como traxectoria",
"{0}: Postprozessor ohne Polar-Interpolation – Flächen als kurze X/C-Schritte (C in Grad) ausgegeben; der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Polar-Interpolation ein/aus“ eintragen":"{0}: posprocesador sen interpolación polar – as caras emítense como pasos curtos X/C (C en graos); segundo o control, o avance non se aplica entón ao longo da traxectoria. É mellor cubrir o modelo „Interpolación polar activada/desactivada“",
"{0}: Postprozessor ohne Vorlage „C-Achse und angetriebenes Werkzeug ein“ – C-Achse und Werkzeugspindel von Hand einschalten":"{0}: Posprocesador sen modelo «Eixe C e ferramenta motorizada activados» – active a man o eixe C e o fuso da ferramenta",
"{0}: Postprozessor ohne Zylinder-Interpolation – Z und C fahren gemeinsam, der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Zylinder-Interpolation ein/aus“ eintragen":"{0}: posprocesador sen interpolación cilíndrica – Z e C móvense xuntos; segundo o control, o avance non se aplica entón ao longo da traxectoria. É mellor cubrir o modelo „Interpolación cilíndrica activada/desactivada“",
"{0}: Postprozessor ohne {1} für diese Form – als Bahn ausgegeben":"{0}: Posprocesador sen {1} para esta forma – emitido como traxectoria",
