"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"«+» = crearase unha ferramenta nova. Os datos de corte son valores orientativos para metal duro ({0}){1}; refrixeración: {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"«Encaixar uns nos outros» coloca os patróns de corte nos ocos e baías dos veciños e nos seus recortes (sen xiro de 90°, só virados 180°); a distancia nunca se reduce. Sen a marca, colócanse en filas segundo o seu rectángulo envolvente. Con «Esbozo + corpos» xéranse corpos planos co grosor da chapa, que na fabricación se poden cortar con contorno 2D.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"“Dentro/Fóra” precisa contornos pechados – fresar as curvas abertas con “Sobre a curva”",
